 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    # Endpoint bars occur in opposite corners and define a diagonal fill
    # region. The isolated marker(s) identify the color to use on each side.
    bg = max(set(v for row in out for v in row), key=lambda c: sum(r.count(c) for r in out))
    bars = {}
    for r in range(h):
        for c in range(w):
            if out[r][c] != bg:
                bars.setdefault(out[r][c], []).append((r,c))
    marker_colors = {c for c, pts in bars.items() if len(pts) == 1}
    # Find distinct corner border bars, and use the singleton markers as
    # thresholds for horizontal/vertical expansion from those corner runs.
    if not marker_colors:
        return out
    mcolor = next(iter(marker_colors))
    # Other non-background colors are corner guide bars.
    guides = [(c,pts) for c,pts in bars.items() if c != mcolor]
    if len(guides) < 2:
        return out
    # Horizontal guide at left/right or top/bottom: paint a triangular region
    # bounded by the guide's extent, switching to marker color at the marker.
    # For the common corner-bar pattern, each guide expands from its border.
    # markers are preserved and all cells within its stepped envelope are filled.
    for gc, pts in guides:
        rs=[p[0] for p in pts]; cs=[p[1] for p in pts]
        if len(set(cs)) == 1:  # vertical bar
            x=cs[0]; lo,hi=min(rs),max(rs)
            for r in range(lo,hi+1):
                for c in range(w):
                    if c != x and out[r][c] == bg:
                        out[r][c]=mcolor
        elif len(set(rs)) == 1: # horizontal bar
            y=rs[0]; lo,hi=min(cs),max(cs)
            for c in range(lo,hi+1):
                for r in range(h):
                    if r != y and out[r][c] == bg:
                        out[r][c]=mcolor
    return out
