 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    # Background is the most frequent color; marker color is the color occurring
    # at isolated interior points. Border guide color has long contiguous runs.
    counts = {}
    for row in out:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    nonbg = {v for row in out for v in row if v != bg}
    # For these puzzles, guide bars occupy the first/last edge segment, markers
    # are single cells in the interior, and output fills a wedge from each bar.
    # Determine marker colors by interior singletons, leaving guide colors intact.
    interiors = {}
    for r in range(1, h-1):
        for c in range(1, w-1):
            v = out[r][c]
            if v != bg:
                interiors[v] = interiors.get(v, 0) + 1
    marker_color = max(interiors, key=interiors.get) if interiors else None
    if marker_color is None:
        return out
    # Construct the wedge between the opposite edge bars: for each marker row,
    # horizontal bars fill toward the nearest side; vertical bars fill vertically.
    # Generalize by identifying the two long border runs.
    edge_runs = []
    for r in range(h):
        for c in (0, w-1):
            v = out[r][c]
            if v != bg:
                rr = r
                while rr < h and out[rr][c] == v: rr += 1
                if rr-r > 1: edge_runs.append((v, 'v', c, r, rr-1))
    for c in range(w):
        for r in (0, h-1):
            v = out[r][c]
            if v != bg:
                cc = c
                while cc < w and out[r][cc] == v: cc += 1
                if cc-c > 1: edge_runs.append((v, 'h', r, c, cc-1))
    # If vertical edge runs bound the upper/lower stripe, fill the rows
    # complementary to those runs up to the marker's column, using marker color.
    for v, orient, fixed, start, end in edge_runs:
        if orient == 'v':
            x = fixed
            # Fill the strip spanning the guide length, toward the marker.
            for r in range(start, end+1):
                for c in range(min(x, w-1), max(x, w-1)+1):
                    if out[r][c] == bg: out[r][c] = marker_color
        else:
            y = fixed
            for c in range(start, end+1):
                for r in range(min(y, h-1), max(y, h-1)+1):
                    if out[r][c] == bg: out[r][c] = marker_color
    return out
