        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    marker_cells = [(r,c,out[r][c]) for r in range(h) for c in range(w)
                    if out[r][c] != bg and 0 < r < h-1 and 0 < c < w-1]
    if not marker_cells:
        return out
    marker_color = marker_cells[0][2]
    # The edge line color is the non-background color that forms long runs
    # along an outer edge. An edge band extends from its border to the marker
    # row/column; the marker determines the inner color transition.
    edge_runs = []
    for c in (0, w-1):
        seq = [out[r][c] for r in range(h)]
        for v in set(seq):
            inds = [r for r,x in enumerate(seq) if x == v]
            if v != bg and len(inds) > 1 and inds == list(range(min(inds), max(inds)+1)):
                edge_runs.append(('v', c, min(inds), max(inds), v))
    for r in (0, h-1):
        seq = out[r]
        for v in set(seq):
            inds = [c for c,x in enumerate(seq) if x == v]
            if v != bg and len(inds) > 1 and inds == list(range(min(inds), max(inds)+1)):
                edge_runs.append(('h', r, min(inds), max(inds), v))
    # For a vertical side bar, paint across the band enclosed by its row span.
    # Use marker color up to marker and color 4 thereafter (the secondary fill).
    for orient, fixed, lo, hi, _ in edge_runs:
        if orient == 'v':
            markers_in_band = [(r,c) for r,c,_ in marker_cells if lo <= r <= hi]
            for r in range(lo, hi+1):
                for c in range(w):
                    if out[r][c] == bg:
                        out[r][c] = marker_color
                for mr,mc in markers_in_band:
                    if r == mr:
                        for c in range(min(fixed,mc)+1, max(fixed,mc)):
                            if out[r][c] == marker_color:
                                out[r][c] = 4
        else:
            markers_in_band = [(r,c) for r,c,_ in marker_cells if lo <= c <= hi]
            for c in range(lo, hi+1):
                for r in range(h):
                    if out[r][c] == bg:
                        out[r][c] = marker_color
