 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    counts = {}
    for row in out:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    # Markers are non-background cells not on the border.
    marks = [(r,c,out[r][c]) for r in range(h) for c in range(w)
             if out[r][c] != bg and 0 < r < h-1 and 0 < c < w-1]
    if not marks:
        return out
    # Paint rectangular bands from each edge guide toward the center.
    # Each guide is a contiguous colored segment on an outer edge.
    runs = []
    for c in (0, w-1):
        vals = [out[r][c] for r in range(h)]
        for v in set(vals):
            ids = [r for r,x in enumerate(vals) if x == v]
            if v != bg and len(ids) >= 2 and ids == list(range(min(ids), max(ids)+1)):
                runs.append(('v', c, min(ids), max(ids)))
    for r in (0, h-1):
        vals = out[r]
        for v in set(vals):
            ids = [c for c,x in enumerate(vals) if x == v]
            if v != bg and len(ids) >= 2 and ids == list(range(min(ids), max(ids)+1)):
                runs.append(('h', r, min(ids), max(ids)))
    for orient, edge, lo, hi in runs:
        if orient == 'v':
            for r in range(lo, hi+1):
                # markers in this row split the fill at their column
                row_marks = sorted(c for rr,c,_ in marks if rr == r)
                if not row_marks:
                    # fill the span, unless the opposite region is outside band
                    continue
                mcol = marks[0][2]
                for c in range(w):
                    if c == edge or out[r][c] != bg: continue
                    out[r][c] = mcol if (c-edge)*(row_marks[0]-edge) <= (row_marks[0]-edge)**2 else 4
                for mc in row_marks:
                    out[r][mc] = mcol
                    step = 1 if mc > edge else -1
                    for c in range(edge+step, mc, step):
                        if out[r][c] == bg: out[r][c] = mcol
                    # beyond marker remains the secondary color
                    for c in range(mc+step, w if step > 0 else -1, step):
                        if out[r][c] == bg: out[r][c] = 4
        else:
            for c in range(lo, hi+1):
                col_marks = sorted(r for r,cc,_ in marks if cc == c)
                if not col_marks: continue
                mcol = marks[0][2]
                for mr in col_marks:
                    out[mr][c] = mcol
                    step = 1 if mr > edge else -1
                    for r in range(edge+step, mr, step):
                        if out[r][c] == bg: out[r][c] = mcol
                    for r in range(mr+step, h if step > 0 else -1, step):
                        if out[r][c] == bg: out[r][c] = 4
    return out
