 "content": "def transform(grid):
    """Extend colored corner bars inward, painting wedge cells from marker rays."""
    out=[row[:] for row in grid]
    h,w=len(out),len(out[0])
    from collections import Counter
    cnt=Counter(x for row in out for x in row)
    bg=cnt.most_common(1)[0][0]
    # marker cells are non-background interior pixels
    marks=[(r,c,out[r][c]) for r in range(h) for c in range(w)
           if out[r][c]!=bg and 0<r<h-1 and 0<c<w-1]
    if not marks: return out
    special=marks[0][2]
    # Locate long colored edge segments (the frame fragments).
    segments=[]
    for c in (0,w-1):
        vals=[out[r][c] for r in range(h)]
        i=0
        while i<h:
            j=i+1
            while j<h and vals[j]==vals[i]: j+=1
            if vals[i]!=bg and j-i>=2: segments.append(('v',c,i,j-1,vals[i]))
            i=j
    for r in (0,h-1):
        vals=out[r]
        i=0
        while i<w:
            j=i+1
            while j<w and vals[j]==vals[i]: j+=1
            if vals[i]!=bg and j-i>=2: segments.append(('h',r,i,j-1,vals[i]))
            i=j
    # A vertical segment expands horizontally across its full row span; a
