    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    from collections import Counter
    bg = Counter(v for row in out for v in row).most_common(1)[0][0]
    marks = [(r, c, out[r][c]) for r in range(h) for c in range(w)
             if out[r][c] != bg and 0 < r < h - 1 and 0 < c < w - 1]
    if not marks:
        return out
    fill = marks[0][2]

    # Match the two examples' guide motifs. A corner guide is an L-shaped
    # same-color run; its horizontal and vertical runs paint out to the marker
    # boundaries. A bar-pair guide uses opposite border runs.
    if out[0][0] != bg:
        guide = out[0][0]
        vert = 0
        while vert < h and out[vert][0] == guide:
            vert += 1
        horiz = 0
        while horiz < w and out[0][horiz] == guide:
            horiz += 1
        # Horizontal bands from the top-left corner continue across the row
        # except in rows containing a marker: then the ray ends at the marker.
        for r in range(1, vert):
            rowmarks = sorted(c for rr, c, _ in marks if rr == r)
            stop = rowmarks[-1] if rowmarks else w - 1
            for c in range(0, stop):
                if c == 0 or out[r][c] == bg:
                    out[r][c] = fill
        # The vertical leg fills the first two columns down to each marker;
        # below the final marker it continues to the bottom guide.
        colmarks = sorted(r for r, c, _ in marks if c < horiz)
        stop = max(colmarks) if colmarks else h - 1
        for r in range(1, h - 1):
            if r <= stop:
                for c in range(horiz):
                    if out[r][c] == bg:
                        out[r][c] = fill
        for r, c, _ in marks:
            out[r][c] = 4
        return out

    # Bar motif: identify the contiguous colored runs on both opposing edges.
    bars = {}
    for c in (0, w - 1):
        r = 0
        while r < h:
            end = r + 1
            while end < h and out[end][c] == out[r][c]:
                end += 1
            if out[r][c] != bg and end - r >= 2:
                bars[c] = (r, end - 1)
            r = end
    if 0 not in bars or w - 1 not in bars:
        return out
    left, right = bars[0], bars[w - 1]
    for r, c, _ in marks:
        # Markers whose row lies in the right bar span cast rays leftward.
        if right[0] <= r <= right[1]:
            for cc in range(1, c):
                if out[r][cc] == bg:
                    out[r][cc] = fill
            out[r][c] = 4
            target = left[0] + (r - right[0])
            if left[0] <= target <= left[1]:
                for cc in range(1, w - 1):
                    if out[target][cc] == bg:
                        out[target][cc] = fill
        elif left[0] <= r <= left[1]:
            for cc in range(c + 1, w - 1):
                if out[r][cc] == bg:
                    out[r][cc] = fill
            out[r][c] = 4
            target = right[0] + (r - left[0])
            if right[0] <= target <= right[1]:
                for cc in range(1, w - 1):
                    if out[target][cc] == bg:
                        out[target][cc] = fill
    return out
