        left_len = 0
        while left_len < h and out[left_len][0] == corner:
            left_len += 1
        top_len = 0
        while top_len < w and out[0][top_len] == corner:
            top_len += 1

        # The sparse cells are points on the rays: fill toward the edge on each
        # ray, and recolor the point as the endpoint.
        for r, c, _ in marks:
            if r < left_len:
                for cc in range(top_len, c):
                    if out[r][cc] == bg:
                        out[r][cc] = fill
                out[r][c] = 4
            if c < top_len:
                for rr in range(left_len, r):
