            e = c + 1
            while e < w and out[r][e] == out[r][c]:
                e += 1
            if out[r][c] != bg and e - c >= 2:
                edge_runs.append((r, c, e - 1, out[r][c]))
            c = e
    for edge, c0, c1, color in edge_runs:
        for c in range(c0, c1 + 1):
            hits = sorted(rr for rr, cc, _ in marks if cc == c)
            if edge == 0:
