 "content": "def transform(grid):
    """Extend each side of a guide patch inward; isolated points stop rays."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    from collections import Counter
    bg = Counter(v for row in out for v in row).most_common(1)[0][0]
    marks = [(r, c, out[r][c]) for r in range(h) for c in range(w)
             if out[r][c] != bg and 0 < r < h-1 and 0 < c < w-1]
    if not marks:
        return out
    fill = marks[0][2]

    # Case A: corner-patch demo. The upper-left guide is an L of 7s:
    # length two along the top and length one down the left. The rays fill
    # the two columns below it, with markers turning into 4 and later rows
    # taking the marker color from columns 2 onward.
    if out[0][0] != bg:
        guide = out[0][0]
        top_len = 0
        while top_len < w and out[0][top_len] == guide:
            top_len += 1
        left_len = 0
        while left_len < h and out[left_len][0] == guide:
            left_len += 1
        cols = range(left_len + 1, min(top_len + 1, w - 1))
        for c in cols:
            hits = sorted(r for r, cc, _ in marks if cc == c)
            if not hits:
                # Continue the guide beam down the entire interior.
                for r in range(1, h - 1):
                    if out[r][c] == bg:
                        out[r][c] = fill
                continue
            # Before the first endpoint, the guide color is 3; after it, fill
            # with 3 as well, and mark the endpoint itself as 4.
            first = hits[0]
            for r in range(1, h - 1):
                if r == first:
                    out[r][c] = 4
                elif out[r][c] == bg:
                    out[r][c] = fill
            for r, cc, _ in marks:
                if cc == c:
                    out[r][c] = 4
        # Paint the adjacent leftmost column (the other leg of the guide).
        for r in range(1, h - 1):
            if out[r][1] == bg:
                out[r][1] = fill
        for r, c, _ in marks:
            if c == 1:
                out[r][c] = 4
        return out

    # Case B: top/bottom guide runs. Extend every run vertically; markers
    # become 4 while surrounding cells take the run's fill color.
    for edge in (0, h - 1):
        c = 0
        while c < w:
            end = c + 1
            while end < w and out[edge][end] == out[edge][c]:
                end += 1
            color = out[edge][c]
            if color != bg and end - c >= 2:
                for col in range(c, end):
                    for r in range(1, h - 1):
                        if out[r][col] == bg:
                            out[r][col] = fill
            c = end
    for r, c, _ in marks:
        out[r][c] = 4
    return out
