        for c in range(c0, c1+1):
            # Extend the boundary guide through the entire interior column.
            for r in range(1, h-1):
                if out[r][c] == bg:
                    out[r][c] = color
    for r, c, _ in markers:
        # Fill the gap between marker and nearest boundary guide along column.
